pub fn spiral(m: List[List[Int]]) -> List[Int] {
  var out: List[Int] = []
  if m.is_empty() {
    return out
  }
  var top = 0
  var bottom = m.len() - 1
  var left = 0
  var right = m.get_or(0, []).len() - 1
  while top <= bottom and left <= right {
    var j = left
    while j <= right {
      out = out.push(m.get_or(top, []).get_or(j, 0))
      j = j + 1
    }
    top = top + 1
    var i = top
    while i <= bottom {
      out = out.push(m.get_or(i, []).get_or(right, 0))
      i = i + 1
    }
    right = right - 1
    if top <= bottom {
      var k = right
      while k >= left {
        out = out.push(m.get_or(bottom, []).get_or(k, 0))
        k = k - 1
      }
      bottom = bottom - 1
    }
    if left <= right {
      var r = bottom
      while r >= top {
        out = out.push(m.get_or(r, []).get_or(left, 0))
        r = r - 1
      }
      left = left + 1
    }
  }
  return out
}
